const i=(n,t,a)=>n<t?t:n>a?a:n;export function spanFor(n,t){const a=i((n-.5)/.8,0,1);return t.narrowSpan+(t.wideSpan-t.narrowSpan)*a}export function distanceFor(n,t,a){const e=Math.atan(Math.tan(a*Math.PI/360)*t);return n/2/Math.tan(e)}export function cameraFor(n,t,a,e,c=null){let r=spanFor(n,t),s=a,g=e;if(c&&e){const o=Math.min(e.x,c.x)-t.includeMargin,y=Math.max(e.x,c.x)+t.includeMargin;r=i(y-o,r,t.maxSpan),g={x:(o+y)/2,z:e.z},s={minX:a.minX,maxX:Math.max(a.maxX,y)}}const h=distanceFor(r,n,t.fovDegrees),u=Math.hypot(t.height,t.back),z=t.height/u,x=t.back/u,f=Math.max(0,(s.maxX-s.minX)/2-r/2+1),X=(s.minX+s.maxX)/2;let m=t.target.x,p=t.target.z;if(g){m=i(g.x,X-f,X+f);const o=1-i((n-.5)/.8,0,1);p=t.target.z+(e.z-t.target.z)*.5*o}if(e&&t.reach){const o=i(e.x,a.minX,a.maxX),M=(h+x*(p-e.z))*Math.tan(t.fovDegrees*Math.PI/360)*n;M>t.reach&&(m=i(m,o+t.reach-M,o-t.reach+M))}return{position:{x:m,y:t.target.y+z*h,z:p+x*h},target:{x:m,y:t.target.y,z:p},span:r,distance:h}}export function cameraOn(n,t,a,e){const c=distanceFor(e,t,a.fovDegrees),r=Math.hypot(a.height,a.back);return{position:{x:n.x,y:a.target.y+a.height/r*c,z:n.z+a.back/r*c},target:{x:n.x,y:a.target.y,z:n.z},span:e,distance:c}}export function cameraCast(n,t,a,e,c=2.2){const r=Math.tan(a.fovDegrees*Math.PI/360),s=c/e.height/(2*r),g=1.4/e.width/(2*r*t),h=Math.max(s,g),u=.3,z=Math.hypot(u,1),x={x:n.x,y:.95,z:n.z};return{position:{x:x.x,y:x.y+u/z*h,z:x.z+h/z},target:x,distance:h}}export function castFrame(n,t){if(n>=720){const a=Math.min(380,n-32)+32;return{width:(n-a)/n,height:1,shiftX:a/2,shiftY:0}}return{width:1,height:.44,shiftX:0,shiftY:t*.28}}export function rayToGround(n,t){if(t.y>=-1e-6)return null;const a=-n.y/t.y;return{x:n.x+t.x*a,z:n.z+t.z*a}}export function ease(n,t,a,e){return t+(n-t)*Math.exp(-a*e)}
